   179  Scope::Scope(Parser& parser,bool topLevel)
   180  {
   181      if(!topLevel) {
   182          TokenPtr t = parser.CurrentToken();
   183          if (t->Type() != TokenType_OPEN_BRACKET) {
   184              ParseError("expected open bracket",t);
   185          }
   186      }
   187
   188      StackAllocator &allocator = parser.GetAllocator();
   189      TokenPtr n = parser.AdvanceToNextToken();
   190      if (n == nullptr) {
   191          ParseError("unexpected end of file");
   192      }
   193
   194      // note: empty scopes are allowed
   195      while(n->Type() != TokenType_CLOSE_BRACKET) {
   196          if (n->Type() != TokenType_KEY) {
   197              ParseError("unexpected token, expected TOK_KEY",n);
   198          }
   199
   200          const std::string& str = n->StringContents();
   201          if (str.empty()) {
   202              ParseError("unexpected content: empty string.");
   203          }
   204
   205          auto *element = new_Element(*n, parser);
   206
   207          // Element() should stop at the next Key token (or right after a Close token)
   208          n = parser.CurrentToken();
   209          if (n == nullptr) {
   210              if (topLevel) {
   211                  elements.insert(ElementMap::value_type(str, element));
   212                  return;
   213              }
   214              delete element;
   215              ParseError("unexpected end of file",parser.LastToken());
   216          } else {
   217              elements.insert(ElementMap::value_type(str, element));
   218          }
   219      }
   220  }
